function showModal(html){content.innerHTML=html;backdrop.classList.remove('hidden');}
function closeModal(){backdrop.classList.add('hidden');content.innerHTML='';}
$('#closeModal').addEventListener('click',closeModal);
backdrop.addEventListener('click',e=>{if(e.target===backdrop)closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
let toastTimer;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function getProfile(){try{return JSON.parse(localStorage.getItem('studyspark_profile')||'null')}catch{return null}}
function getStudyEvents(){try{return JSON.parse(localStorage.getItem('studyspark_activity')||'[]')}catch{return []}}
function trackStudyEvent(type){const events=getStudyEvents();events.push({type,date:new Date().toISOString().slice(0,10),at:Date.now()});localStorage.setItem('studyspark_activity',JSON.stringify(events.slice(-500)));renderStudyDashboard()}
function renderStudyDashboard(){
 const events=getStudyEvents();const now=new Date();const dayKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
 const start=new Date(now);start.setHours(0,0,0,0);start.setDate(start.getDate()-6);const startKey=dayKey(start);const recent=events.filter(e=>e.date>=startKey&&e.date<=dayKey(now));
 const goal=5;const pct=Math.min(100,Math.round(recent.length/goal*100));const ring=$('#progressRing');if(ring)ring.style.background=`conic-gradient(#a88cff 0 ${pct}%,#29334f ${pct}% 100%)`;
 const percent=$('#progressPercent');if(percent)percent.textContent=`${pct}%`;
 const headline=$('#progressHeadline');if(headline)headline.textContent=recent.length===0?'Ready when you are!':recent.length>=goal?'Goal reached — great work!':'You’re building momentum!';
 const message=$('#progressMessage');if(message)message.textContent=`${recent.length} of ${goal} weekly study activities completed.`;
 const bars=$('#weeklyBars');if(bars){bars.innerHTML='';for(let i=0;i<7;i++){const d=new Date(start);d.setDate(start.getDate()+i);const k=dayKey(d);const count=events.filter(e=>e.date===k).length;const bar=document.createElement('i');bar.style.height=`${Math.max(4,Math.min(100,count*28))}%`;bar.title=`${k}: ${count} ${count===1?'activity':'activities'}`;bar.setAttribute('aria-label',bar.title);bars.appendChild(bar)}}
 const status=$('#saveStatusTitle');if(status)status.textContent=events.length?'Progress saved locally':'Ready to track progress';const sub=$('#saveStatusText');if(sub)sub.textContent=events.length?'Saved on this browser only':'Complete a note or quiz';
}

function showAuth(mode='signup'){
  const isSignup=mode==='signup';
  showModal(`<div class="eyebrow">YOUR LEARNING SPACE</div><h2 id="modalTitle">${isSignup?'Create your demo profile':'Welcome back'}</h2><p>${isSignup?'Use a nickname to personalise this local demo.':'Enter the nickname you used on this device.'}</p><form id="authForm"><label class="modal-label" for="nick">Nickname</label><input class="modal-input" id="nick" required maxlength="24" placeholder="e.g. StudyStar" value="${getProfile()?.name||''}"><button class="btn btn-primary" type="submit" style="width:100%">${isSignup?'Create demo profile':'Continue'} →</button></form><p class="modal-note">Prototype only: this does not create a secure account or sync between devices. Real login needs a backend.</p>`);
  $('#authForm').addEventListener('submit',e=>{e.preventDefault();const name=$('#nick').value.trim();if(!name)return;localStorage.setItem('studyspark_profile',JSON.stringify({name}));closeModal();toast(`Welcome, ${name}! Demo profile saved on this device.`);renderLeaderboard()});
}
