function grammarCategory(rule){const t=(rule.title||'').toLowerCase();
 if(/each|every/.test(t))return 'eachEvery'; if(/both|neither|either|nor/.test(t))return 'neither';
 if(/relative pronoun|who, whom|who\/whom|whom|whose|which and that/.test(t))return 'relative';
 if(/conditional|if there|unless/.test(t))return 'conditional'; if(/one of|either of|each of/.test(t))return 'oneof';
 if(/number.*unit|unit.*noun|year-old|hour|kilomet|weight|height|distance|speed/.test(t))return 'unit';
 if(/time, money|money, speed|singular verb|amount/.test(t))return 'amount';
 if(/compar|elder|older|younger|than/.test(t))return /elder|older/.test(t)?'elderOlder':'comparison';
 if(/pronoun|possessive|apostrophe|objective case|me, him, her/.test(t))return /possessive|apostrophe/.test(t)?'possessive':'pronoun';
 if(/tense|verb|past participle|past perfect|present perfect|future/.test(t))return 'tense';
 if(/preposition|between|from.*to|interested|good at/.test(t))return /between/.test(t)?'between':'preposition';
 if(/uncountable|plural|noun|fewer|less/.test(t))return /fewer|less/.test(t)?'fewerLess':'noun';
 if(/adverb|very|much|manner/.test(t))return /very|much/.test(t)?'veryMuch':'adverb';
 return 'general';}
function shuffleArray(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function buildGrammarPartQuiz(part){
 const start=(part-1)*30+1,end=part*30,questions=[];
 // Every rule contributes all ten practice items in its mapped concept pool:
 // 30 rules × 10 questions = 300 questions in each part.
 for(let n=start;n<=end;n++){
  const rule=grammar120Rules.find(r=>r.n===n);if(!rule)continue;
  const pool=grammarQuestionPools[grammarCategory(rule)]||grammarQuestionPools.general;
  pool.forEach((raw,qIndex)=>{
   const optionPairs=raw[1].map((text,i)=>({text,correct:i===raw[2]}));
   const shuffled=shuffleArray(optionPairs);
   const cleanTitle=rule.title.replace(/^Rule\s*\d+\s*:\s*/i,'');
   questions.push({
    ruleNumber:n,
    q:`Rule ${String(n).padStart(3,'0')} · ${cleanTitle} · Question ${qIndex+1} of 10\n\n${raw[0]}`,
    options:shuffled.map(o=>o.text),
    answer:shuffled.findIndex(o=>o.correct),
    explain:`Rule focus: ${rule.focus||cleanTitle}. ${raw[3]}`
   });
  });
 }
 return {title:`120 Rules · Part ${part} (${start}–${end}) · ${questions.length} questions`,questions:shuffleArray(questions)};
}

