const rulePdfExamples = {"1": ["talented.", "He has a book in each hand."], "2": ["this place.", "this place."], "3": ["reading.", "reading."], "4": ["I condition possible to fulfill"], "5": ["phrase \"one of the\" is:"], "6": ["“Number + Unit + Noun” or, “Number +"], "7": ["weight, height and distance, when used or"], "8": ["metals.", "other metals."], "9": ["had completed my graduation.", "completed my graduation."], "10": ["him.", "him."], "11": ["your car.", "your car."], "12": ["it began to rain.", "it began to rain."], "13": ["We go to church on fridays.", "We go to the church on fridays."], "14": ["sooner”, “Hardly”, “Scarcely”, etc. are"], "15": ["He hid himself in the room.", "He hid in the room."], "16": ["his life.", "life."], "17": ["were arrested.", "was arrested."], "18": ["for similar sounding words, like"], "19": ["him.", "3.She is taller than me"], "20": ["“Who” is used as a subjective pronoun, and"], "21": ["sad.", "I become sad."], "22": ["All citizens should love one other."], "23": ["house."], "24": ["match."], "25": ["“Enough” plays the role of both Adverb and"], "26": ["“as” can be used as an adverb with these"], "27": ["before spending a penny.", "before spending a penny."], "28": ["I am owning a car.", "I own a car."], "29": ["arrived.", "been there?"], "30": ["When a collective noun denotes that the"], "31": ["always followed by the preposition “to”."], "32": ["He is as good as Ram.", "He is not as good as Ram."], "33": ["book.", "that book."], "34": ["He asked me where are you going.", "He asked me where I was going."], "35": ["the words \"or,\" \"nor,\" \"neither/nor,\""], "36": ["This pen is redder than white.", "This book is heavier than larger."], "37": ["“many a” is used to quantify a noun, it is"], "38": ["not.", "not."], "39": ["sweet.", "sweet."], "40": ["We use these quantifiers with uncountable"], "41": ["None but he is going to the party.", "None but him is going to the party."], "42": ["Subject, when all the three persons are used as"], "43": ["today’s match.", "match."], "44": ["Table’s legs.", "Door’s bolt."], "45": ["purchase a car.", "car."], "46": ["He is the most excellent student.", "He is an excellent student."], "47": ["He is quite all well.", "He is quite well."], "48": ["He had gone two seconds ago.", "He went two seconds ago."], "49": ["for Balram’s marriage.", "marriage."], "50": ["The child is carrying it’s book.", "The child is carrying its book."], "51": ["We use the following structures with these"], "52": ["is high time” or “It is about time”:"], "53": ["(1)We use the preposition “with” with"], "54": ["I don't know to make tea"], "55": ["followed by “but” while the adverbs “other,"], "56": ["etc.” are always followed by a Singular verb."], "57": ["“in”, “Inside” and “into”:"], "58": ["(1)We use “with” when we refer non-living"], "59": ["My exams start from Monday.", "My exams start on Monday."], "60": ["always use the form “To + V1”. But in certain"], "61": ["indefinite articles – ‘a’ & ‘an’ – is determined"], "62": ["(1)Series of Mountains, Bays/Gulfs,Group of"], "63": ["not use any article before following nouns:"], "64": ["Whenever the article “the” is used before an"], "65": ["the terrorists.", "the terrorists."], "66": ["plurals should be known:"], "67": ["She went to a female doctor.", "treated."], "68": ["The noun or pronoun that comes just before"], "69": ["A small question is added at the end of a"], "70": ["students, amn’t I?", "students, aren’t I?"], "71": ["hardly, scarcely, never” often define a"], "72": ["me, don’t I?", "me, aren’t I?"], "73": ["both ends meet, hasn’t he?", "both ends meet, haven’t they?"], "74": ["the main statement and depicting all its units"], "75": ["Let us go for a walk, don’t we?", "Let us go for a walk, shall we?"], "76": ["‘In’ refers to town, cities, and countries in a"], "77": ["English.", "English."], "78": ["Work hard, lest you would fail.", "Work hard, lest you fail."], "79": ["Unless – Action Oriented"], "80": ["I like singing, dancing, and walking.", "prepare the dish."], "81": ["It is important to use exact prepositions after"], "82": ["He is too much strong.", "He is much too strong."], "83": ["His belongings were lost.", "His earnings are not enough."], "84": ["When the word “Politics” is considered as"], "85": ["our strategy.", "our strategy."], "86": ["mean “One of many” and the article “The”"], "87": ["I have brought a bag too.", "I have brought a bag as well."], "88": ["The sentence which expresses a prayer, keen"], "89": ["school.", "Being ill, he did not come to class."], "90": ["a sentence talks about a noun, it is always"], "91": ["watch this movie."], "92": ["savings, congratulations, scissors, proceeds,"], "93": ["subject.", "Mathematics is a difficult subject."], "94": ["His luggages was booked.", "His luggage was booked."], "95": ["Types of Conditional Sentences:"], "96": ["My all students are very talented.", "All my students are very talented."], "97": ["go to his house.", "his house."], "98": ["Little quantity of food was wasted.", "Few quantity of food was wasted."], "99": ["banks.", "organization."], "100": ["(1) We use this “Lie” to say or write"], "101": ["We use either the preposition “of” or “from”"], "102": ["Beside is a preposition, which means at"], "103": ["He behaved friendly.", "He behaved in a friendly manner."], "104": ["He comes often to my house.", "He often comes to my house."], "105": ["I walked yesterday slowly."], "106": ["In a sentence, both these terms are used"], "107": ["pm to 5 pm.", "pm and 5 pm."], "108": ["cannot be converted into their plural."], "109": ["I am an English teacher.", "He is a Mathematics teacher."], "110": ["Everyone should do one’s duty.", "Everyone should do his duty."], "111": ["work.", "the work."], "112": ["me.", "than me."], "113": ["Mumbai.", "weather of Mumbai."], "114": ["visit NASA.", "NASA."], "115": ["All but he are going to the party.", "All but him are going to the party."], "116": ["It is him who should be blamed.", "It is he who should be blamed."], "117": ["mentioned.", "mentioned."], "118": ["Government girls’s school.", "Government girls’ school."], "119": ["Your’s friendly.", "Yours friendly."], "120": ["are never followed by Noun. These are"]};
function ruleDeepDiveMeta(rule){
 const t=(rule.title||'').toLowerCase();
 const groups=[
  [/\beach\b|\bevery\b|\bboth\b|\bneither\b|\beither\b|\bone of the\b|\bmore than one\b|\bmany a\b|\bfewer\b|\bless\b|\belder\b|\bolder\b|\bcollective noun|\bsubject.?verb|\bnumber of\b|\bamount of\b|\bplural noun/i,'Agreement & quantity','First identify the expression that controls the sentence, then decide whether it refers to one unit, individual members, or a plural set. Do not let a nearby noun distract you from the grammatical subject. Check both the noun form and the verb form.','Underline the subject phrase, cross out extra information between subject and verb, and read the sentence again with the verb. For quantity words, ask whether the noun is countable and whether the sentence refers to number or amount.'],
  [/\bwho\b|\bwhom\b|\bwhich\b|\bthat\b|\bpronoun\b|\breflexive\b|\bpossessive\b|\beach other\b|\bone another\b|\bcase of pronoun\b/i,'Pronouns & reference','Find the noun the pronoun refers to, then identify the pronoun’s job in its clause. A subject form performs the action; an object form receives it or follows a preposition. Possessive and reflexive forms have separate jobs.','Read the clause without the relative clause first. Then test the pronoun inside its own clause: “___ called” needs a subject form; “I called ___” needs an object form. Make sure the reference is clear.'],
  [/\btense\b|\bpast perfect\b|\bconditional\b|\bnarration\b|\bindirect speech\b|\bdirect speech\b|\bvoice\b|\binversion\b|\bno sooner\b|\bhardly\b|\bscarcely\b|\bseldom\b|\bwhenever\b|\buntil\b|\bwhile\b|\bwhen\b/i,'Tense, narration & sentence order','Map the time and sequence before selecting a verb form. Decide whether the sentence describes a fact, a repeated action, a hypothetical situation, an earlier past event, or reported speech. Some opening adverbs and conjunctions also require a particular clause order.','Mark the time signal and locate the main clause. For inversion, check whether the auxiliary comes before the subject; for reported speech, preserve meaning while adjusting tense, pronouns and time/place words when required.'],
  [/\bpreposition\b|\bsince\b|\bfor\b|\balthough\b|\bconjunction\b|\benough\b|\badverb\b|\badjective\b|\bgerund\b|\b-ing\b|\bnon.?finite\b|\bverb\b|\badvice\b|\badvise\b|\bpractice\b|\bpractise\b|\bword\b/i,'Word form, modifiers & connectors','Identify the grammatical role of the target word in this sentence—not just its dictionary meaning. Check what it modifies, what form must follow it, and whether the combination is a standard English pattern. Similar-looking words can belong to different parts of speech.','Test the word in its slot: does the sentence need a noun, verb, adjective, adverb, gerund or infinitive? Then check the word that follows the connector or preposition. Learn frequent combinations as complete chunks.'],
  [/\bcompar|\bas\.\.\.as\b|\bso\.\.\.as\b|\bmore\b|\bmost\b|\bdegree\b|\bparallel\b|\bnumber \+ unit\b|\btime, money\b/i,'Comparison & parallel structure','Compare like with like: the same kind of person, thing, action or quality. Check whether the sentence needs a positive, comparative or superlative form and whether both sides use matching structures.','Name the two items being compared. If one side compares a person with a group, or a noun with an action, rewrite the sentence so the comparison is logically balanced.'],
  [/\barticle\b|\ba \/ an\b|\bapostrophe\b|\bpossessive case\b|\bplural\b|\bnoun\b|\bcountable\b|\buncountable\b/i,'Nouns, articles & possession','Check whether the noun is singular or plural, countable or uncountable, and whether ownership is being shown. Articles depend on sound, specificity and context; apostrophes mark possession or contractions, not ordinary plurals.','Ask whether the noun is countable, whether it is specific or general, and whether possession is intended. Then check apostrophe placement and avoid adding an apostrophe to a plain plural.']
 ];
 for(const g of groups) if(g[0].test(t)) return {category:g[1],explanation:g[2],method:g[3]};
 return {category:'Rule application & error spotting',explanation:'Treat the heading as the target construction, then test the complete sentence for grammatical form and intended meaning. This study page keeps the PDF rule numbering and expands it into a readable lesson rather than copying the PDF page layout.',method:'Locate the exact phrase being tested, identify the grammatical job it performs, and compare choices by changing only that phrase. Read the full sentence again to confirm the meaning.'};
}
function highlightRuleText(value){
 let out=escapeHTML(value);
 const words=['Each','Every','Both','Neither','Either','Who','Whom','Which','That','Subject','Verb','Singular','Plural','Pronoun','Antecedent','Preposition','Gerund','Infinitive','Past Perfect','Conditional','Comparative','Superlative','Apostrophe','Countable','Uncountable','Main clause','If-clause','Auxiliary'];
 words.sort((a,b)=>b.length-a.length).forEach(w=>{const re=new RegExp('(?<![\\w-])('+w.replace(/[.*+?^${}()|[\\]\\]/g,'\\$&')+')(?![\\w-])','gi');out=out.replace(re,'<strong>$1</strong>')});
 return out;
}
function rulePageHtml(rule){
 const meta=ruleDeepDiveMeta(rule), ex=(rulePdfExamples[String(rule.n)]||[]).slice(0,2);
 const extra=makeExtraRuleExamples(rule);
 return `<div class="deep-rule-kicker">RULE ${String(rule.n).padStart(3,'0')} · ${escapeHTML(meta.category)}</div>
 <section class="deep-rule-section"><h3>📌 Core idea</h3><p>${highlightRuleText(meta.explanation)}</p></section>
 <section class="deep-rule-section"><h3>🧭 How to solve it in an exam</h3><ol><li>Read the whole sentence once for meaning.</li><li>${highlightRuleText(meta.method)}</li><li>Check the word immediately before and after the target phrase.</li><li>Reject options that are grammatical in isolation but do not fit the sentence’s meaning.</li></ol></section>
 <section class="deep-rule-section source-example"><h3>📖 Example cue from the PDF</h3>${ex.length?ex.map(x=>`<p class="example-line">${escapeHTML(x)}</p>`).join(''):'<p>The source lesson covers this construction; use the rule heading and the worked examples in the source PDF to check the exact pattern.</p>'}<p class="source-note">Short example cue from your uploaded grammar material; wording and layout here are adapted for easier screen reading.</p></section>
 <section class="deep-rule-section extra-example"><h3>✍️ More examples</h3>${extra.map(x=>`<p class="example-line">${x}</p>`).join('')}</section>
 <section class="deep-rule-section exam-trap"><h3>⚠️ Common trap</h3><p>Do not choose an answer just because a familiar keyword appears. Identify the grammatical role, check the complete structure, and preserve the intended meaning.</p></section>
 <section class="deep-rule-section memory-check"><h3>🧠 Quick self-check</h3><p>Can you explain the rule without looking, create one correct example, and explain why a near-miss version is wrong? If not, pause here before pressing Next.</p></section>`;
}
function makeExtraRuleExamples(rule){
 const t=(rule.title||'').toLowerCase();
 let lines=['The candidate who arrived early found a seat.','Read the entire sentence before choosing the option.'];
 if(/each|every/.test(t)) lines=['Each of the answers is worth one mark.','Every applicant must bring an identity card.'];
 else if(/both|neither|either/.test(t)) lines=['Neither Riya nor Aman is available today.','Both the teams are ready.'];
 else if(/who|whom|which|that|relative pronoun/.test(t)) lines=['The student who solved the problem explained it.','The book that you lent me is useful.'];
 else if(/conditional/.test(t)) lines=['If she practises, she will improve.','If I had known, I would have called.'];
 else if(/since|for/.test(t)) lines=['She has lived here for five years.','They have been waiting since noon.'];
 else if(/past perfect|tense|narration|speech/.test(t)) lines=['The train had left before we reached the station.','He said that he was feeling better.'];
 else if(/comparison|comparative|degree|as… as|as\.\.\. as/.test(t)) lines=['This route is shorter than the other one.','Mira is as careful as her sister.'];
 else if(/gerund|possessive adjective/.test(t)) lines=['I appreciate your helping me.','We objected to his arriving late.'];
 else if(/reflexive/.test(t)) lines=['She prepared herself for the interview.','The children enjoyed themselves at the fair.'];
 else if(/fewer|less|countable|uncountable/.test(t)) lines=['Fewer students were absent today.','There is less water in this bottle.'];
 else if(/advice|advise|practice|practise|noun and verb/.test(t)) lines=['The teacher gave useful advice.','I advise you to check the instructions.'];
 else if(/apostrophe|possession|possessive/.test(t)) lines=['The girls’ uniforms are blue.','The child’s bag is on the desk.'];
 else if(/preposition/.test(t)) lines=['She is interested in science.','We arrived at the station on time.'];
 return lines.map(x=>escapeHTML(x));
}
function openRuleDeepDive(startIndex=0,backAction=()=>openSubject('English')){
 let idx=Math.max(0,Math.min(119,startIndex));
 const render=()=>{
  const rule=grammar120Rules[idx];
  showModal(`<div class="deep-dive-workspace"><div class="eyebrow">ENGLISH · GRAMMAR · DEEP DIVE</div><div class="deep-dive-heading"><div><h2 id="modalTitle">${escapeHTML(rule.title)}</h2><p>Detailed study page · Source rule ${rule.n} of 120</p></div><button class="btn btn-outline" id="deepDiveExit">✕ Exit deep dive</button></div><div class="deep-dive-progress"><div class="deep-dive-progress-label"><span>PROGRESS</span><strong>${idx+1} / 120 · ${Math.round((idx+1)/120*100)}%</strong></div><div class="rule-progress"><span style="width:${(idx+1)/120*100}%"></span></div><label for="ruleJump">Jump to a rule</label><select id="ruleJump" class="rule-jump-select">${grammar120Rules.map((r,i)=>`<option value="${i}" ${i===idx?'selected':''}>Rule ${String(r.n).padStart(3,'0')} — ${escapeHTML(r.desc||r.title.replace(/^Rule \d+:?\s*/,''))}</option>`).join('')}</select></div><div class="deep-rule-content">${rulePageHtml(rule)}</div><div class="rule-slider deep-dive-controls"><div class="rule-slider-controls"><button class="btn btn-outline" id="prevDeepRule" ${idx===0?'disabled':''}>← Previous rule</button><strong>Rule ${rule.n} of 120</strong><button class="btn btn-primary" id="nextDeepRule" ${idx===119?'disabled':''}>Next rule →</button></div><div class="rule-slider-hint">Keyboard navigation: ← previous · → next · Home first rule · End last rule</div></div><button class="btn btn-outline" id="deepDiveBack">← Back to Grammar folder</button></div>`);
  $('#prevDeepRule')?.addEventListener('click',()=>{idx=Math.max(0,idx-1);render()});
  $('#nextDeepRule')?.addEventListener('click',()=>{idx=Math.min(119,idx+1);render()});
  $('#ruleJump')?.addEventListener('change',e=>{idx=Number(e.target.value)||0;render()});
  $('#deepDiveExit')?.addEventListener('click',backAction);$('#deepDiveBack')?.addEventListener('click',backAction);
  document.onkeydown=ev=>{if(ev.key==='ArrowRight'&&idx<119){idx++;render()}else if(ev.key==='ArrowLeft'&&idx>0){idx--;render()}else if(ev.key==='Home'){idx=0;render()}else if(ev.key==='End'){idx=119;render()}};
 };
 render();
}
