 showModal(`<div class="eyebrow">ENGLISH · GRAMMAR</div><h2 id="modalTitle">120 Rules — Practice Tests</h2><p>Choose a part to practise. Each test covers its 30 numbered rules.</p><div class="rule-test-buttons">${[1,2,3,4].map(part=>`<button class="btn btn-primary" data-start-rule-part="${part}">Part ${part} · Rules ${(part-1)*30+1}–${part*30} →</button>`).join('')}</div><button class="btn btn-outline" id="closeGrammarTestPicker">← Back to rule</button>`);
 $('#closeGrammarTestPicker').onclick=()=>openChapterLesson('English',grammar120Rules[0],'120 Rules of English Grammar',()=>openSubject('English'),grammar120Rules,0);
