function openChapterLesson(subject,lesson,parentTitle,backAction,siblings=[],index=-1){
 const isRule=Number.isInteger(lesson.n)&&lesson.n>=1&&lesson.n<=120;
 const render=idx=>{
  const current=isRule?siblings[idx]:lesson;
  if(!current)return;
  const nav=`<div class="rule-slider-controls"><button class="btn btn-outline" id="prevRule" ${idx===0?'disabled':''}>← Previous</button><strong>Rule ${current.n} of 120</strong><button class="btn btn-primary" id="nextRule" ${idx===siblings.length-1?'disabled':''}>Next →</button></div>`;
  showModal(`<div class="eyebrow">${escapeHTML(subject.toUpperCase())} · ${isRule?'120 RULES SLIDE '+current.n:'CHAPTER NOTES'}</div>${isRule?`<div class="rule-slider rule-slider-top-controls"><div class="rule-slider-top"><span>SLIDE ${String(current.n).padStart(3,'0')} / 120</span><span>${Math.round(current.n/120*100)}% complete</span></div><div class="rule-progress"><span style="width:${current.n/120*100}%"></span></div>${nav}</div>`:''}<h2 id="modalTitle">${escapeHTML(current.title)}</h2><div class="chapter-body">${escapeHTML(current.body||'This chapter is ready for study notes.').replace(/\n/g,'<br>')}</div>${isRule?`<div class="rule-slider rule-slider-bottom">${nav}<div class="rule-slider-hint">Use Next or Previous to move one rule at a time. You can also use the ← and → arrow keys.</div><button class="btn btn-outline" id="openGrammarTests" style="margin-top:12px;width:100%">✍ Take the 120 Rules test</button></div>`:''}<button class="btn btn-outline" id="backToParent">← Back to ${escapeHTML(parentTitle||subject)}</button>${!isRule?'<button class="btn btn-primary" id="chapterQuiz">Try chapter quiz →</button>':''}`);
  $('#backToParent').onclick=()=>{document.onkeydown=null;if(backAction)backAction()};
  if(!isRule)$('#chapterQuiz').onclick=()=>startQuiz(subject==='Maths'&&/Simplification/i.test(current.title)?'simplification':(subject==='GK'?'criminalLaw':'math'));
  if(isRule){
   $('#prevRule')?.addEventListener('click',()=>{if(idx>0)render(idx-1)});
   $('#nextRule')?.addEventListener('click',()=>{if(idx<siblings.length-1)render(idx+1)});
   $('#openGrammarTests')?.addEventListener('click',openGrammarTestPicker);
   document.onkeydown=ev=>{if(ev.key==='ArrowRight'&&idx<siblings.length-1)render(idx+1);if(ev.key==='ArrowLeft'&&idx>0)render(idx-1)};
  } else document.onkeydown=null;
 };
 if(isRule&&index>=0)render(index);else render(-1);
}

function renderPortalPanel(subject,tab){const info=subjectInfo[subject]||{chapters:[]};const panel=$('#portalPanel');if(!panel)return;if(tab==='summary'&&(subject==='GK'||subject==='English')){const summaries=subject==='GK'?[{title:'Criminal Law (BNS, BNSS & BSA)',desc:'Three separate criminal-law codes with different roles.',body:'BNS: substantive criminal law—offences, definitions and punishments. BNSS: criminal procedure—police powers, investigation, arrest, bail, trial and related processes. BSA: evidence law—relevance, admissibility and proof, including electronic/digital evidence. Study each law separately, then compare the corresponding provisions and verify current amendments/commencement.'},{title:'General Knowledge: History, Polity, Geography, Economy & Science',desc:'Core static-GK revision map.',body:'History: timelines, movements, rulers, causes and consequences. Polity: Constitution, institutions, rights, duties and governance. Geography: physical features, climate, rivers, resources, maps and population. Economy: inflation, GDP, banking, budget, fiscal/monetary policy and key indicators. Science: basic principles, everyday applications, space, biology, technology and environment. Connect stable facts to dated current affairs; recheck changing data before exams.'}]:[{title:'Vocabulary',desc:'Word meaning and usage.',body:'Synonyms: similar meanings; Antonyms: opposite meanings; One Word Substitution: one word replacing a phrase; Idioms and Phrases: figurative fixed expressions; Spelling/Commonly Confused Words: correct forms and distinctions; Phrasal Verbs: verb + particle meanings; Collocations: words that naturally occur together. Learn words in context and revise with example sentences.'},{title:'Grammar',desc:'Rules, sentence structure and error spotting.',body:'Start with parts of speech and sentence structure. Then revise subject–verb agreement, pronouns, nouns, tense and verb forms, articles/determiners, prepositions, conjunctions, adjectives/adverbs, comparison, conditionals, non-finites, voice, narration, question tags, parallelism and common error patterns. The 120 Rules folder preserves the rule numbering from your PDF; use the numbered rule slides and Quick Summary together.'},{title:'Reading & Verbal Ability',desc:'Comprehension and sentence-level skills.',body:'Reading Comprehension: identify the central idea, evidence, tone and inference. Cloze Test: use grammar, context and collocation. Para Jumbles: find opening sentence, links, pronoun references and logical sequence. Sentence Completion: check meaning, grammar and connectors. Practise explaining why each option fits or fails.'}];panel.innerHTML=`<div class="summary-intro"><h3>${subject==='GK'?'GK — Topic Summary':'English — Topic Summary'}</h3><p>Quick revision across the main folders. Open Notes & chapters for detailed explanations and individual chapters.</p></div><div class="portal-grid">${summaries.map((x,i)=>`<article class="portal-card summary-card"><span class="portal-number">SUMMARY ${String(i+1).padStart(2,'0')}</span><h3>${escapeHTML(x.title)}</h3><p>${escapeHTML(x.desc)}</p><div class="summary-body">${escapeHTML(x.body).replace(/\n/g,'<br>')}</div></article>`).join('')}</div>${subject==='English'?`<article class="portal-card summary-rule-index"><span class="portal-number">120 RULES</span><h3>120 Rules — Rapid Revision Index</h3><p>Use the source-numbered summary to scan all rules, then open an individual rule for its detailed notes and example.</p><button class="btn btn-outline" data-open-120-summary>Open 120 Rules summary →</button></article>`:''}`;const open120=panel.querySelector('[data-open-120-summary]');if(open120)open120.onclick=()=>{const g=subjectInfo.English.chapters.find(c=>c.title==='Grammar');const summary=g?.children?.find(c=>c.title==='120 Rules — Quick Summary');if(summary){showModal(`<div class="eyebrow">ENGLISH · RAPID REVISION</div><h2 id="modalTitle">${escapeHTML(summary.title)}</h2><div class="chapter-body">${escapeHTML(summary.body).replace(/\n/g,'<br>')}</div><button class="btn btn-outline" id="backToEnglishSummary">← Back to Summary</button>`);$('#backToEnglishSummary').onclick=()=>openSubject('English')}};return}else if(tab==='notes'){panel.innerHTML=`<div class="portal-grid">${info.chapters.map((c,i)=>`<article class="portal-card"><span class="portal-number">${c.children?'TOPIC':'CHAPTER'} ${String(i+1).padStart(2,'0')}</span><h3>${escapeHTML(c.title)}</h3><p>${escapeHTML(c.desc)}</p><button class="btn btn-outline" data-chapter="${i}">${c.children?'Open topic →':'Read notes →'}</button></article>`).join('')}</div>`}else if(tab==='tests'){if(subject==='English'){panel.innerHTML=`<div class="summary-intro"><h3>120 Rules — Four Practice Parts</h3><p>Choose a part below to start its 300-question test. Each part covers 30 rules, with 10 questions assigned to each rule, and shuffles question order and answer choices.</p></div><div class="portal-grid">${[1,2,3,4].map(part=>`<article class="portal-card"><span class="portal-number">PART ${part} · RULES ${(part-1)*30+1}–${part*30}</span><h3>120 Rules — Part ${part}</h3><p>300 questions · 10 per rule · 60-minute limit · shuffled questions and options.</p><button class="btn btn-primary" data-start-subject-quiz="grammar120part${part}">Start Part ${part} →</button></article>`).join('')}</div><p class="modal-note">Each part contains 300 question entries, with 10 items assigned to every rule in that part. The pool uses original practice questions organised by grammar concept; review explanations carefully and report any item that needs correction.</p>`}else{const testItems=info.chapters.flatMap((c,i)=>c.children?c.children.map((child,j)=>({title:child.title,desc:child.desc,topic:c.title,groupIndex:i,childIndex:j})): [{title:c.title,desc:c.desc,topic:'',groupIndex:i,childIndex:-1}]);panel.innerHTML=`<div class="portal-grid">${testItems.map((c,i)=>`<article class="portal-card"><span class="portal-number">${escapeHTML(c.topic||'TOPIC TEST')}</span><h3>${escapeHTML(c.title)} — Practice Test</h3><p>${escapeHTML(c.desc)} Practice this topic separately from your notes.</p><button class="btn btn-primary" data-start-subject-quiz="${subject==='Maths'&&/Simplification/i.test(c.title)?'simplification':((subject==='GK'||subject==='Current Affairs')&&/Criminal Law|BNS|BNSS|BSA|Digital Justice|Criminal-law update/i.test(c.title+' '+c.topic)?'criminalLaw':'math')}">Start test →</button></article>`).join('')}</div><p class="modal-note">Topic-specific test cards are organised here. Criminal-law test cards use a dedicated BNS/BNSS/BSA question set. Other subjects may still share starter question sets until their individual banks are added.</p>`}}else{const items=info.chapters.flatMap((c,i)=>c.children?c.children.map((child,j)=>({...child,parent:c.title,index:i,subIndex:j})): [{...c,index:i}]);panel.innerHTML=`<div class="portal-grid">${items.map(c=>`<article class="portal-card"><span class="portal-number">QUICK REVISION${c.parent?' · '+escapeHTML(c.parent):''}</span><h3>${escapeHTML(c.title)}</h3><p>${escapeHTML(c.desc)}</p><button class="btn btn-outline" data-chapter="${c.index}">Open revision →</button></article>`).join('')}</div>`}}
$$('[data-subject-filter]').forEach(b=>b.addEventListener('click',()=>openSubject(b.dataset.subjectFilter)));
function filterResources(){const term=$('#resourceSearch').value.toLowerCase();let count=0;$$('.resource-card').forEach(card=>{const subjectMatch=currentSubject==='All'||card.dataset.subject===currentSubject;const match=subjectMatch&&(currentFilter==='All'||card.dataset.category===currentFilter)&&(`${card.dataset.search} ${card.innerText}`).toLowerCase().includes(term);card.classList.toggle('hidden',!match);if(match)count++});$('#emptyResources').classList.toggle('hidden',count!==0);const heading=$('#resources .section-heading h2');if(heading)heading.innerHTML=currentSubject==='All'?'Knowledge, <span class="gradient-text">organised.</span>':`${currentSubject} <span class="gradient-text">resources.</span>`}
$$('.open-resource').forEach(b=>b.addEventListener('click',()=>{trackStudyEvent('notes');showModal(`<div class="eyebrow">LEARNING LIBRARY</div><h2 id="modalTitle">${escapeHTML(b.dataset.title)}</h2><p style="white-space:pre-line">${escapeHTML(b.dataset.body)}</p><p class="modal-note">Starter sample content. Replace or expand this with your own syllabus-aligned materials.</p><button class="btn btn-primary" id="closeResource">Got it ✓</button>`)}));
$('#modalContent').addEventListener('click',e=>{if(e.target.id==='closeResource')closeModal()});
$('#menuBtn').addEventListener('click',()=>$('.nav-links').classList.toggle('open'));
$$('.nav-links a').forEach(a=>a.addEventListener('click',()=>$('.nav-links').classList.remove('open')));
$('#adminBtn').addEventListener('click',()=>showModal(`<div class="eyebrow">ADMIN PANEL PREVIEW</div><h2 id="modalTitle">Admin workspace</h2><p>This is a visual preview, not a secure admin console.</p><div class="admin-item"><strong>Resource library</strong><br>Manage notes, PDFs, subjects, and download links once a backend is connected.</div><div class="admin-item"><strong>Quiz builder</strong><br>Create questions, answer choices, explanations, and point values.</div><div class="admin-item"><strong>Users & leaderboard</strong><br>Review user profiles and scores using server-enforced permissions.</div><p class="modal-note">Never protect admin access with a frontend-only password. Real admin roles must be checked by the database/server.</p><button class="btn btn-primary" id="closeAdmin">Close preview</button>`));
$('#modalContent').addEventListener('click',e=>{if(e.target.id==='closeAdmin')closeModal()});
renderLeaderboard();
renderStudyDashboard();
